svg.script:
(function () {
  var svg = document.documentElement;
  var group = document.getElementById("ccgarden-scrubber");
  var input = document.getElementById("ccgarden-scrubber-input");
  var label = document.getElementById("ccgarden-scrubber-label");
  var duration = 5;
  var keyTimes = [0,0.14,0.29,0.43,0.57,0.71,0.86,1];
  var dayLabels = ["Jul 26, 2026","Jul 27, 2026","Jul 28, 2026","Jul 29, 2026","Jul 30, 2026","Jul 31, 2026","Aug 1, 2026","Aug 2, 2026"];
  var paused = false;
  function reveal() {
    group.style.opacity = "1";
    group.style.pointerEvents = "auto";
  }
  function seek(dayIndex) {
    if (!paused) { svg.pauseAnimations(); paused = true; }
    svg.setCurrentTime(keyTimes[dayIndex] * duration);
    label.textContent = dayLabels[dayIndex];
  }
  input.addEventListener("input", function () {
    seek(parseInt(input.value, 10));
  });
  window.setTimeout(reveal, duration * 1000 + 150);
})();

(function () {
  var svg = document.documentElement;
  var group = document.getElementById("ccgarden-tooltip");
  var box = document.getElementById("ccgarden-tooltip-box");
  var text = document.getElementById("ccgarden-tooltip-text");
  var pad = 8.0;
  var boxHeight = 29.0;
  var viewWidth = 800.0;
  var viewHeight = 948.0;
  var keyTimes = [0,0.14,0.29,0.43,0.57,0.71,0.86,1];
  var duration = 5;
  function currentDayIndex() {
    var t = svg.getCurrentTime();
    if (duration <= 0 || t >= duration) {
      return keyTimes.length - 1;
    }
    var frac = t / duration;
    var idx = 0;
    for (var i = 0; i < keyTimes.length; i++) {
      if (keyTimes[i] <= frac + 1e-6) { idx = i; } else { break; }
    }
    return idx;
  }
  function findTooltip(node) {
    while (node && node !== svg) {
      if (node.id === "ccgarden-scrubber") { return null; }
      var days = node.getAttribute
        ? node.getAttribute("data-tt")
        : null;
      if (days) {
        var list = JSON.parse(days);
        var idx = Math.min(currentDayIndex(), list.length - 1);
        return { label: list[idx], dynamic: true };
      }
      var kids = node.childNodes || [];
      for (var i = 0; i < kids.length; i++) {
        if (kids[i].nodeName === "title") {
          return { label: kids[i].textContent, dynamic: false };
        }
      }
      node = node.parentNode;
    }
    return null;
  }
  function toUserSpace(event) {
    var ctm = svg.getScreenCTM();
    if (!ctm) { return null; }
    var point = svg.createSVGPoint();
    point.x = event.clientX;
    point.y = event.clientY;
    return point.matrixTransform(ctm.inverse());
  }
  function hide() { group.setAttribute("opacity", "0"); }
  function show(label, at) {
    text.textContent = label;
    var width = text.getComputedTextLength() + pad * 2;
    box.setAttribute("width", width.toFixed(1));
    var x = at.x - width / 2;
    var y = at.y - boxHeight - 14;
    if (x < 4) { x = 4; }
    if (x + width > viewWidth - 4) {
      x = viewWidth - 4 - width;
    }
    if (y < 4) { y = at.y + 18; }
    if (y + boxHeight > viewHeight - 4) {
      y = viewHeight - 4 - boxHeight;
    }
    group.setAttribute(
      "transform",
      "translate(" + x.toFixed(1) + "," + y.toFixed(1) + ")"
    );
    group.setAttribute("opacity", "1");
  }
  var dynamicNodes = svg.querySelectorAll("[data-tt]");
  for (var d = 0; d < dynamicNodes.length; d++) {
    var dKids = dynamicNodes[d].childNodes;
    for (var k = dKids.length - 1; k >= 0; k--) {
      if (dKids[k].nodeName === "title") {
        dynamicNodes[d].removeChild(dKids[k]);
      }
    }
  }
  svg.addEventListener("pointerdown", function (event) {
    if (event.pointerType === "mouse") { return; }
    var found = findTooltip(event.target);
    var at = found ? toUserSpace(event) : null;
    if (at) { show(found.label, at); } else { hide(); }
  });
  svg.addEventListener("pointermove", function (event) {
    if (event.pointerType !== "mouse") { return; }
    var found = findTooltip(event.target);
    if (found && found.dynamic) {
      show(found.label, toUserSpace(event));
    } else {
      hide();
    }
  });
  // A touch pointer "leaves" the moment the finger lifts, which
  // would undo the tap we just handled -- only a cursor exit.
  svg.addEventListener("pointerleave", function (event) {
    if (event.pointerType !== "mouse") { return; }
    hide();
  });
})();
